"""Exact money: whole minor units plus a currency code."""
import re

from tallybook._util import is_int
from tallybook.currency import CURRENCIES, CurrencyError, currency as _currency
from tallybook.errors import ValidationError


class MoneyError(ValidationError):
    """A bad amount or an operation mixing currencies."""


def round_div(n, d):
    """n / d rounded to the nearest integer, halves away from zero."""
    if not is_int(n) or not is_int(d):
        raise MoneyError("round_div needs integers, got %r and %r" % (n, d))
    if d <= 0:
        raise MoneyError("round_div needs a positive divisor, got %r" % (d,))
    q, r = divmod(abs(n), d)
    if 2 * r >= d:
        q += 1
    return q if n >= 0 else -q


def _exponent(code):
    return _currency(code).exponent


def format_minor(minor, currency):
    """The amount text of a number of minor units: -5 USD -> '-0.05'."""
    e = _exponent(currency)
    if not is_int(minor):
        raise MoneyError("amount must be an integer number of minor units, got %r" % (minor,))
    sign = "-" if minor < 0 else ""
    digits = str(abs(minor))
    if e == 0:
        return sign + digits
    digits = digits.rjust(e + 1, "0")
    return sign + digits[:-e] + "." + digits[-e:]


_AMOUNT_RE = re.compile(r"([+-]?)([0-9]+)(?:\.([0-9]+))?")


def parse_amount(text, currency):
    """Read an amount typed by hand and return its minor units as an int."""
    e = _exponent(currency)
    if not isinstance(text, str):
        raise MoneyError("invalid amount %r: not text" % (text,))
    m = _AMOUNT_RE.fullmatch(text)
    if not m:
        raise MoneyError("invalid amount '%s'" % text)
    sign, whole, frac = m.groups()
    if frac is not None:
        if e == 0:
            raise MoneyError("invalid amount '%s': %s has no decimals" % (text, currency))
        if len(frac) > e:
            raise MoneyError("invalid amount '%s': %s has only %d decimals" % (text, currency, e))
    else:
        frac = ""
    value = int(whole + frac.ljust(e, "0"))
    return -value if sign == "-" else value


class Money:
    """An immutable amount of one currency, in minor units."""

    __slots__ = ("_minor", "_currency")

    def __init__(self, minor, currency):
        Currency("MXN", 2, "Mexican Peso", "MX$"),
    ]
}


def is_currency(code):
    return isinstance(code, str) and code in CURRENCIES


def currency(code):
    """Return the Currency for a code, or raise CurrencyError."""
    if not is_currency(code):
        if isinstance(code, str):
            raise CurrencyError("unknown currency '%s'" % code)
        raise CurrencyError("unknown currency %r" % (code,))
    return CURRENCIES[code]


_RATE_RE = re.compile(r"[0-9]+(?:\.[0-9]{1,8})?")


def parse_rate_text(text):
    """Check a rate text and return it as an exact Fraction (CurrencyError if bad)."""
    if not isinstance(text, str) or not _RATE_RE.fullmatch(text):
        raise CurrencyError("invalid rate %r" % (text,) if not isinstance(text, str)
                            else "invalid rate '%s'" % text)
    value = Fraction(text)
    if value <= 0:
        raise CurrencyError("invalid rate '%s': must be positive" % text)
    return value


def _check_date(on):
    if not is_date(on):
        raise CurrencyError("invalid date %r: expected a datetime.date" % (on,))


def _fmt(d):
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


class RateTable:
    """Exchange rates by day; one unit of src buys rate units of dst."""

    def __init__(self):
        self._rates = {}  # (src, dst) -> {date: Fraction}

    def set(self, src, dst, rate_text, on):
        currency(src)
        currency(dst)
        if src == dst:
            raise CurrencyError("cannot set a rate from %s to itself" % src)
        value = parse_rate_text(rate_text)
        _check_date(on)
        self._rates.setdefault((src, dst), {})[on] = value

    def _latest(self, src, dst, on):
        table = self._rates.get((src, dst))
        if not table:
            return None
        best = None
        for d in table:
            if d <= on and (best is None or d > best):
                best = d
        return None if best is None else table[best]

    def rate(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        if src == dst:
            return Fraction(1)
        direct = self._latest(src, dst, on)
        if direct is not None:
            return direct
        inverse = self._latest(dst, src, on)
        if inverse is not None:
            return 1 / inverse
        raise CurrencyError("no rate %s -> %s on %s" % (src, dst, _fmt(on)))

    def convert(self, money, dst, on):
        from tallybook.money import Money, round_div

        if not isinstance(money, Money):
            raise CurrencyError("cannot convert %r: not a Money" % (money,))
        currency(dst)
        _check_date(on)
        if money.currency == dst:
            return money
        r = self.rate(money.currency, dst, on)
        diff = CURRENCIES[dst].exponent - CURRENCIES[money.currency].exponent
        num = money.minor * r.numerator
        den = r.denominator
        if diff >= 0:
            num *= 10 ** diff
        else:
            den *= 10 ** (-diff)
        return Money(round_div(num, den), dst)

    def entries(self):
        out = []
        for (src, dst), table in self._rates.items():
            for d, value in table.items():
                out.append((src, dst, d, value))
        out.sort(key=lambda e: (e[0], e[1], e[2]))
        return out

    def remove(self, src, dst, on):
        currency(src)
        currency(dst)
        _check_date(on)
        table = self._rates.get((src, dst))
        if not table or on not in table:
            raise CurrencyError("no rate %s -> %s set on %s" % (src, dst, _fmt(on)))
        del table[on]
        if not table:
            del self._rates[(src, dst)]

    def copy(self):
        new = RateTable()
        new._rates = {k: dict(v) for k, v in self._rates.items()}
        return new
"""Dates, months and periods; strict YYYY-MM-DD everywhere."""
import datetime as _dt
import re

from tallybook._util import is_date, is_int
from tallybook.errors import ParseError


class DateError(ParseError):
    """A malformed date or period, or a date outside the calendar."""


_DATE_RE = re.compile(r"([0-9]{4})-([0-9]{2})-([0-9]{2})")


def _show(text):
    return "'%s'" % text if isinstance(text, str) else repr(text)


def parse_date(text):
    if not isinstance(text, str):
        raise DateError("invalid date %r: expected text YYYY-MM-DD" % (text,))
    m = _DATE_RE.fullmatch(text)
    if not m:
        raise DateError("invalid date '%s': expected YYYY-MM-DD" % text)
    try:
        return _dt.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    except ValueError:
        raise DateError("invalid date '%s': no such day" % text) from None


def format_date(d):
    if not is_date(d):
        raise DateError("not a date: %r" % (d,))
    return "%04d-%02d-%02d" % (d.year, d.month, d.day)


def last_day(year, month):
    if not is_int(year) or not is_int(month):
        raise DateError("year and month must be integers, got %r and %r" % (year, month))
    if not 1 <= month <= 12:
        raise DateError("invalid month %d" % month)
    if not 1 <= year <= 9999:
        raise DateError("invalid year %d" % year)
    if month == 12:
        return 31
    return (_dt.date(year, month + 1, 1) - _dt.timedelta(days=1)).day


def add_months(d, n):
    if not is_date(d):
        raise DateError("not a date: %r" % (d,))
    if not is_int(n):
        raise DateError("number of months must be an integer, got %r" % (n,))
    index = d.year * 12 + (d.month - 1) + n
    year, month0 = divmod(index, 12)
    if not 1 <= year <= 9999:
        raise DateError("date out of range: %s moved by %d months" % (format_date(d), n))
    month = month0 + 1
    return _dt.date(year, month, min(d.day, last_day(year, month)))


_STEPS = ("week", "month", "quarter", "year")


def _period_containing(d, step):
    if step == "week":
        s = _add_days(d, -d.weekday()) if d.toordinal() - d.weekday() >= 1 else _dt.date(1, 1, 1)
        return Period(s, _add_days(s, 6) if s.toordinal() + 6 <= _dt.date.max.toordinal()
                      else _dt.date.max)
    if step == "month":
        return Period(_dt.date(d.year, d.month, 1), _dt.date(d.year, d.month, last_day(d.year, d.month)))
    if step == "quarter":
        mo = (d.month - 1) // 3 * 3 + 1
        return Period(_dt.date(d.year, mo, 1), _dt.date(d.year, mo + 2, last_day(d.year, mo + 2)))
