"""Export transactions as CSV and JSON, and lay out plain text tables."""
import json

from tallybook._util import is_date, is_int
from tallybook.dates import DateError, format_date, parse_date
from tallybook.errors import TallybookError, ValidationError
from tallybook.model import Posting, Transaction
from tallybook.money import Money, format_minor, parse_amount

__all__ = [
    "ExportError", "transactions_to_csv", "to_csv", "transactions_to_json", "transactions_from_json",
    "money_to_dict", "transaction_to_dict", "to_json", "render_table",
]


class ExportError(ValidationError):
    """A table or a JSON document that cannot be exported or read back."""


CSV_HEADER = ["id", "date", "flag", "payee", "narration", "tags", "account", "amount", "currency", "note"]


# -- small pieces ---------------------------------------------------------

def _text(value):
    return "" if value is None else str(value)


def _date_text(value):
    if is_date(value):
        return format_date(value)
    return _text(value)


def _tags(tags):
    if tags is None:
        return []
    if isinstance(tags, str):
        return [tags]
    return sorted(set(tags))


def _amount_text(money):
    return format_minor(money.minor, money.currency)


def money_to_dict(money):
    """{"amount": "12.50", "currency": "USD"} for a Money, None for None."""
    if money is None:
        return None
    if not isinstance(money, Money):
        raise ExportError("not a Money: %r" % (money,))
    return {"amount": _amount_text(money), "currency": money.currency}


def transaction_to_dict(tx):
    """One transaction as a JSON-able dict."""
    return {
        "id": tx.id,
        "date": _date_text(tx.date),
        "flag": tx.flag,
        "payee": tx.payee,
        "narration": tx.narration,
        "tags": _tags(tx.tags),
        "postings": [{"account": p.account, "amount": money_to_dict(p.amount), "note": p.note}
                     for p in (tx.postings or [])],
    }


def to_json(value):
    """The project's JSON text: indent 2, sorted keys, UTF-8 as is, one trailing newline."""
    return json.dumps(value, indent=2, sort_keys=True, ensure_ascii=False) + "\n"


# -- CSV ------------------------------------------------------------------

def _csv_field(value):
    text = _text(value)
    if any(ch in text for ch in ',"\r\n'):
        return '"' + text.replace('"', '""') + '"'
    return text


def _csv_record(cells):
    return ",".join(_csv_field(c) for c in cells) + "\n"


def to_csv(headers, rows):
    """Any table as CSV: header record first, minimal quoting, '\\n' line ends."""
    out = [_csv_record(list(headers))]
    for row in rows:
        out.append(_csv_record(list(row)))
    return "".join(out)


def transactions_to_csv(txs):
    """One CSV record per posting, header first."""
    rows = []
    for tx in txs:
        head = [
            "" if tx.id is None else str(tx.id),
            _date_text(tx.date),
            _text(tx.flag),
            _text(tx.payee),
            _text(tx.narration),
            ";".join(_tags(tx.tags)),
        ]
        postings = list(tx.postings or [])
        if not postings:
            rows.append(head + ["", "", "", ""])
