            rows.append(head + [_text(p.account), amount, cur, _text(p.note)])
    return to_csv(CSV_HEADER, rows)


# -- JSON -----------------------------------------------------------------

def transactions_to_json(txs):
    """A JSON array with one object per transaction, in the given order."""
    return to_json([transaction_to_dict(tx) for tx in txs])


_TX_KEYS = {"id", "date", "flag", "payee", "narration", "tags", "postings"}
_POSTING_KEYS = {"account", "amount", "note"}


def _read_money(where, value):
    if value is None:
        return None
    if not isinstance(value, dict) or set(value) != {"amount", "currency"}:
        raise ExportError("%s: amount must be null or an object with keys amount and currency" % where)
    amount, code = value["amount"], value["currency"]
    if not isinstance(amount, str) or not isinstance(code, str):
        raise ExportError("%s: amount and currency must be text" % where)
    try:
        return Money(parse_amount(amount, code), code)
    except TallybookError as e:
        raise ExportError("%s: %s" % (where, e.message)) from None


def _read_posting(where, item):
    if not isinstance(item, dict):
        raise ExportError("%s: a posting must be an object" % where)
    unknown = sorted(set(item) - _POSTING_KEYS)
    if unknown:
        raise ExportError("%s: unknown key '%s'" % (where, unknown[0]))
    if "account" not in item or not isinstance(item["account"], str):
        raise ExportError("%s: account must be text" % where)
    note = item.get("note", "")
    if not isinstance(note, str):
        raise ExportError("%s: note must be text" % where)
    amount = _read_money(where, item.get("amount"))
    return Posting(item["account"], amount, note)


def _read_transaction(where, item):
    if not isinstance(item, dict):
        raise ExportError("%s: a transaction must be an object" % where)
    unknown = sorted(set(item) - _TX_KEYS)
    if unknown:
        raise ExportError("%s: unknown key '%s'" % (where, unknown[0]))
    for key in ("date", "payee", "postings"):
        if key not in item:
            raise ExportError("%s: missing %s" % (where, key))
    date_text = item["date"]
    if not isinstance(date_text, str):
        raise ExportError("%s: date must be YYYY-MM-DD text" % where)
    try:
        day = parse_date(date_text)
    except DateError as e:
        raise ExportError("%s: %s" % (where, e.message)) from None
    tx_id = item.get("id")
    if tx_id is not None and (not is_int(tx_id) or tx_id < 1):
        raise ExportError("%s: id must be null or a whole number of at least 1" % where)
    flag = item.get("flag", "*")
    if flag not in ("*", "!") or not isinstance(flag, str):
        raise ExportError("%s: flag must be * or !" % where)
    payee = item["payee"]
    if not isinstance(payee, str):
        raise ExportError("%s: payee must be text" % where)
    narration = item.get("narration", "")
    if not isinstance(narration, str):
        raise ExportError("%s: narration must be text" % where)
    tags = item.get("tags", [])
    if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
        raise ExportError("%s: tags must be a list of text" % where)
    postings = item["postings"]
    if not isinstance(postings, list):
        raise ExportError("%s: postings must be a list" % where)
    read = [_read_posting("%s posting %d" % (where, j), p) for j, p in enumerate(postings, 1)]
    return Transaction(day, payee, narration, read, tuple(sorted(set(tags))), flag, tx_id)


def transactions_from_json(text):
    """Read the text made by transactions_to_json back into a list of Transaction."""
    if not isinstance(text, str):
        raise ExportError("not JSON text: %r" % (type(text).__name__,))
    try:
        data = json.loads(text)
    except ValueError as e:
        raise ExportError("not valid JSON: %s" % e) from None
    if not isinstance(data, list):
        raise ExportError("the JSON is not an array of transactions")
    return [_read_transaction("transaction %d" % i, item) for i, item in enumerate(data, 1)]


# -- tables ---------------------------------------------------------------

def _cell(value):
    text = "" if value is None else str(value)
    return text.replace("\t", " ").replace("\r", " ").replace("\n", " ")


def render_table(headers, rows, align=None):
    """Fixed-width text: titles, a rule of dashes, one line per row."""
    titles = [_cell(h) for h in headers]
    if not titles:
        return ""
    n = len(titles)
    if align is None:
        aligns = ["l"] * n
    else:
        if not isinstance(align, (str, list, tuple)):
            raise ExportError("align must be a string, list or tuple of 'l'/'r', got %r" % (align,))
        aligns = list(align)
        for a in aligns:
            if a not in ("l", "r") or not isinstance(a, str):
                raise ExportError("invalid alignment %r: expected 'l' or 'r'" % (a,))
        if len(aligns) != n:
            raise ExportError("align has %d letters for %d columns" % (len(aligns), n))
    body = []
    for i, row in enumerate(rows, 1):
        try:
            cells = [_cell(c) for c in row]
        except TypeError:
            raise ExportError("row %d is not a sequence of cells" % i) from None
        if len(cells) != n:
            raise ExportError("row %d has %d cells, expected %d" % (i, len(cells), n))
        body.append(cells)
    widths = [len(t) for t in titles]
    for cells in body:
        for k, c in enumerate(cells):
            if len(c) > widths[k]:
                widths[k] = len(c)

    def line(cells):
        parts = [c.ljust(w) if a == "l" else c.rjust(w) for c, w, a in zip(cells, widths, aligns)]
        return "  ".join(parts).rstrip(" ") + "\n"

    out = [line(titles), line(["-" * w for w in widths])]
    out.extend(line(cells) for cells in body)
    return "".join(out)

