"""Reports: plain dicts describing where the book stands, as text or CSV."""
from tallybook._util import is_date
from tallybook.currency import currency as _check_currency
from tallybook.dates import Period, format_date, periods
from tallybook.errors import ValidationError
from tallybook.export import render_table, to_csv
from tallybook.money import Money, format_minor, round_div

__all__ = [
    "ReportError", "trial_balance", "balance_sheet", "income_statement", "cashflow", "register",
    "net_worth", "render_text", "report_to_csv",
]


class ReportError(ValidationError):
    """A report asked for with bad arguments, or a value that is not a report."""


REPORTS = ("trial_balance", "balance_sheet", "income_statement", "cashflow", "register", "net_worth")
STEPS = ("week", "month", "quarter", "year")

_ROOT_TYPES = {
    "Assets": "asset",
    "Liabilities": "liability",
    "Equity": "equity",
    "Income": "income",
    "Expenses": "expense",
}


# -- helpers --------------------------------------------------------------

def _type(path):
    return _ROOT_TYPES.get(path.split(":", 1)[0])


def _m(minor, cur):
    return {"amount": format_minor(minor, cur), "currency": cur}


def _md(money):
    return _m(money.minor, money.currency)


def _money_list(sums, keep_zero=True):
    return [_m(sums[c], c) for c in sorted(sums) if keep_zero or sums[c] != 0]


def _percent(part, total):
    """part / total as a percentage text with one decimal, halves away from zero."""
    if total == 0:
        return "0.0"
    if total < 0:
        part, total = -part, -total
    q = round_div(part * 1000, total)
    sign = "-" if q < 0 else ""
    q = abs(q)
    return "%s%d.%d" % (sign, q // 10, q % 10)


def _check_ledger(ledger):
    # Duck-typed: anything with the Ledger reading interface works.
    if not hasattr(ledger, "postings") or not hasattr(ledger, "chart"):
        raise ReportError("not a ledger: %r" % (ledger,))


def _check_as_of(as_of):
    if as_of is not None and not is_date(as_of):
        raise ReportError("as_of must be a date or None, got %r" % (as_of,))


def _check_period(period, allow_none=False):
    if period is None and allow_none:
        return
    if not isinstance(period, Period):
        raise ReportError("period must be a Period, got %r" % (period,))


def _postings(ledger, start=None, end=None):
    """(tx, posting) pairs with a dated amount, start/end inclusive when given."""
    for tx, p in ledger.postings():
        if p.amount is None:
            continue
        if start is not None and tx.date < start:
            continue
        if end is not None and tx.date > end:
            continue
        yield tx, p


def _account_sums(ledger, start=None, end=None, types=None):
    """{(account, currency): minor} over postings in the window, optionally filtered by type."""
    sums = {}
    for tx, p in _postings(ledger, start, end):
        if types is not None and _type(p.account) not in types:
            continue
        key = (p.account, p.amount.currency)
        sums[key] = sums.get(key, 0) + p.amount.minor
    return sums


def _add(sums, cur, minor):
    sums[cur] = sums.get(cur, 0) + minor


# -- trial balance --------------------------------------------------------

def trial_balance(ledger, as_of=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    sums = _account_sums(ledger, end=as_of)
    accounts = []
    debits, credits = {}, {}
    for (acc, cur) in sorted(sums):
        v = sums[(acc, cur)]
        if v == 0:
            continue
        debits.setdefault(cur, 0)
        credits.setdefault(cur, 0)
        if v > 0:
            debits[cur] += v
            accounts.append({"account": acc, "type": _type(acc), "debit": _m(v, cur), "credit": None})
        else:
            credits[cur] += -v
            accounts.append({"account": acc, "type": _type(acc), "debit": None, "credit": _m(-v, cur)})
    totals = [{"currency": cur, "debit": _m(debits[cur], cur), "credit": _m(credits[cur], cur),
               "balanced": debits[cur] == credits[cur]} for cur in sorted(debits)]
    return {"report": "trial_balance", "as_of": format_date(as_of) if as_of is not None else None,
            "accounts": accounts, "totals": totals}


# -- balance sheet --------------------------------------------------------

def balance_sheet(ledger, as_of=None, convert_to=None, today=None):
    _check_ledger(ledger)
    _check_as_of(as_of)
    if convert_to is not None:
        _check_currency(convert_to)
        if as_of is None:
            raise ReportError("converting to %s needs an as_of date" % (convert_to,))
    sums = _account_sums(ledger, end=as_of)
    sections = {"asset": [], "liability": [], "equity": []}
    retained = {}
    for (acc, cur) in sorted(sums):
        v = sums[(acc, cur)]
        t = _type(acc)
        if t in ("income", "expense"):
            _add(retained, cur, -v)
            continue
        if v == 0 or t not in sections:
            continue
        sections[t].append((acc, Money(v if t == "asset" else -v, cur)))
    retained_list = [Money(retained[c], c) for c in sorted(retained) if retained[c] != 0]

    def convert(money):
        return ledger.rates.convert(money, convert_to, as_of)

    out = {"report": "balance_sheet", "as_of": format_date(as_of) if as_of is not None else None,
           "currency": convert_to}
    totals_by_section = {}
    for key, t in (("assets", "asset"), ("liabilities", "liability"), ("equity", "equity")):
        lines = []
        total = {}
        for acc, money in sections[t]:
            if convert_to is None:
                lines.append({"account": acc, "balance": _md(money)})
                _add(total, money.currency, money.minor)
            else:
                conv = convert(money)
                lines.append({"account": acc, "balance": _md(conv), "original": _md(money)})
                _add(total, conv.currency, conv.minor)
        section = {"accounts": lines}
        if t == "equity":
            if convert_to is None:
                section["retained_earnings"] = [_md(m) for m in retained_list]
                for m in retained_list:
                    _add(total, m.currency, m.minor)
            else:
                if retained_list:
                    s = 0
                    for m in retained_list:
                        s += convert(m).minor
                    section["retained_earnings"] = [_m(s, convert_to)]
                    _add(total, convert_to, s)
                else:
                    section["retained_earnings"] = []
        if convert_to is not None:
            total = {convert_to: total.get(convert_to, 0)}
        section["total"] = _money_list(total)
        totals_by_section[key] = total
        out[key] = section
    a, l, e = totals_by_section["assets"], totals_by_section["liabilities"], totals_by_section["equity"]
    curs = set(a) | set(l) | set(e)
    out["balanced"] = all(a.get(c, 0) == l.get(c, 0) + e.get(c, 0) for c in curs)
    return out


# -- income statement -----------------------------------------------------

def income_statement(ledger, period, convert_to=None):
    _check_ledger(ledger)
    _check_period(period)
    if convert_to is not None:
        _check_currency(convert_to)
    sums = _account_sums(ledger, period.start, period.end, types=("income", "expense"))
    raw = {"income": [], "expense": []}
    for (acc, cur) in sorted(sums):
        v = sums[(acc, cur)]
        if v == 0:
            continue
        t = _type(acc)
        raw[t].append((acc, Money(-v if t == "income" else v, cur)))
    out = {"report": "income_statement", "start": format_date(period.start), "end": format_date(period.end),
           "currency": convert_to}
    totals = {}
    for key, t in (("income", "income"), ("expenses", "expense")):
        items = []  # (account, shown money, original money)
        for acc, money in raw[t]:
            shown = money if convert_to is None else ledger.rates.convert(money, convert_to, period.end)
            items.append((acc, shown, money))
        total = {}
        for _, shown, _ in items:
            _add(total, shown.currency, shown.minor)
        if convert_to is not None:
            total = {convert_to: total.get(convert_to, 0)}
        lines = []
        for acc, shown, money in items:
            line = {"account": acc, "amount": _md(shown)}
            if convert_to is not None:
                line["original"] = _md(money)
            line["percent"] = _percent(shown.minor, total.get(shown.currency, 0))
            lines.append(line)
        out[key] = {"accounts": lines, "total": _money_list(total)}
        totals[key] = total
    inc, exp = totals["income"], totals["expenses"]
    out["net"] = _money_list({c: inc.get(c, 0) - exp.get(c, 0) for c in set(inc) | set(exp)})
    return out


# -- cash flow ------------------------------------------------------------

def cashflow(ledger, period):
    _check_ledger(ledger)
    _check_period(period)
    start, end = period.start, period.end
    opening, closing = {}, {}
    for tx, p in _postings(ledger, end=end):
        if _type(p.account) != "asset":
            continue
        cur = p.amount.currency
        closing.setdefault(cur, 0)
        opening.setdefault(cur, 0)
        closing[cur] += p.amount.minor
        if tx.date < start:
            opening[cur] += p.amount.minor
    contrib = {}
    for tx in ledger.transactions():
        if tx.date < start or tx.date > end:
            continue
        asset_sum = {}
        for p in tx.postings:
            if p.amount is not None and _type(p.account) == "asset":
                _add(asset_sum, p.amount.currency, p.amount.minor)
        for p in tx.postings:
            if p.amount is None or _type(p.account) == "asset":
                continue
            if asset_sum.get(p.amount.currency, 0) == 0:
                continue
            key = (p.account, p.amount.currency)
            contrib[key] = contrib.get(key, 0) - p.amount.minor
    inflows, outflows = [], []
    total_in = {c: 0 for c in closing}
    total_out = {c: 0 for c in closing}
    for (acc, cur) in sorted(contrib):
        v = contrib[(acc, cur)]
        if v > 0:
            inflows.append({"account": acc, "amount": _m(v, cur)})
            _add(total_in, cur, v)
        elif v < 0:
            outflows.append({"account": acc, "amount": _m(-v, cur)})
            _add(total_out, cur, -v)
    curs = set(closing) | set(total_in) | set(total_out)
    net = {c: total_in.get(c, 0) - total_out.get(c, 0) for c in curs}
    return {"report": "cashflow", "start": format_date(start), "end": format_date(end),
            "opening": _money_list(opening), "inflows": inflows, "outflows": outflows,
            "total_in": _money_list(total_in), "total_out": _money_list(total_out),
            "net": _money_list(net), "closing": _money_list(closing)}


# -- register -------------------------------------------------------------

def register(ledger, account, period=None, rollup=False):
    _check_ledger(ledger)
    if not isinstance(account, str) or not ledger.chart.exists(account):
        raise ReportError("no such account %s" % (account,))
    _check_period(period, allow_none=True)
    start = period.start if period is not None else None
    end = period.end if period is not None else None
    prefix = account + ":"

    def selected(path):
        return path == account or (rollup and path.startswith(prefix))

    opening = {}
    rows_raw = []
    for tx, p in _postings(ledger, end=end):
        if not selected(p.account):
            continue
        cur = p.amount.currency
        opening.setdefault(cur, 0)
        if start is not None and tx.date < start:
            opening[cur] += p.amount.minor
        else:
            rows_raw.append((tx, p))
    running = dict(opening)
    rows = []
    for tx, p in rows_raw:
        cur = p.amount.currency
        running[cur] += p.amount.minor
        rows.append({"date": format_date(tx.date), "id": tx.id, "payee": tx.payee, "narration": tx.narration,
                     "account": p.account, "amount": _md(p.amount), "balance": _m(running[cur], cur)})
    return {"report": "register", "account": account, "rollup": bool(rollup),
            "start": format_date(start) if start is not None else None,
            "end": format_date(end) if end is not None else None,
            "opening": _money_list(opening), "rows": rows, "closing": _money_list(running)}


# -- net worth ------------------------------------------------------------

def net_worth(ledger, period, step="month"):
    _check_ledger(ledger)
    _check_period(period)
    if not isinstance(step, str) or step not in STEPS:
        raise ReportError("unknown step %r: expected week, month, quarter or year" % (step,))
    steps = periods(period.start, period.end, step)
    entries = [(tx.date, _type(p.account), p.amount) for tx, p in _postings(ledger)
               if _type(p.account) in ("asset", "liability")]
    points = []
    for st in steps:
        day = st.end
        assets, liabilities = {}, {}
        for d, t, money in entries:
            if d > day:
                continue
            assets.setdefault(money.currency, 0)
            liabilities.setdefault(money.currency, 0)
            if t == "asset":
                assets[money.currency] += money.minor
            else:
                liabilities[money.currency] -= money.minor
        net = {c: assets[c] - liabilities[c] for c in assets}
        points.append({"date": format_date(day), "assets": _money_list(assets),
                       "liabilities": _money_list(liabilities), "net": _money_list(net)})
    return {"report": "net_worth", "start": format_date(period.start), "end": format_date(period.end),
            "step": step, "points": points}


# -- text -----------------------------------------------------------------

def _mt(money):
    return "%s %s" % (money["amount"], money["currency"])


def _blocks(*blocks):
    rows = []
    for block in blocks:
        if not block:
            continue
        if rows:
            rows.append(None)
        rows.extend(block)
    return rows


def _fill(rows, n):
    return [[""] * n if r is None else r for r in rows]


def _report_kind(report):
    if not isinstance(report, dict) or report.get("report") not in REPORTS:
        raise ReportError("not a report: %r" % (report,))
    return report["report"]


def _text_trial_balance(r):
    title = "Trial balance as of %s" % r["as_of"] if r["as_of"] is not None else "Trial balance"
    rows = []
    for a in r["accounts"]:
        rows.append([a["account"], a["type"], _mt(a["debit"]) if a["debit"] else "",
                     _mt(a["credit"]) if a["credit"] else ""])
    for t in r["totals"]:
        rows.append(["Total", "", _mt(t["debit"]), _mt(t["credit"])])
    return title, ["Account", "Type", "Debit", "Credit"], rows, "llrr"


def _text_balance_sheet(r):
    title = "Balance sheet as of %s" % r["as_of"] if r["as_of"] is not None else "Balance sheet"
    if r.get("currency") is not None:
        title += " (in %s)" % r["currency"]
    blocks = []
    for key, heading in (("assets", "Assets"), ("liabilities", "Liabilities"), ("equity", "Equity")):
        sec = r[key]
        block = [[heading, ""]]
        block += [["  " + a["account"], _mt(a["balance"])] for a in sec["accounts"]]
        if key == "equity":
            block += [["  Retained earnings", _mt(m)] for m in sec["retained_earnings"]]
        block += [["Total " + key, _mt(m)] for m in sec["total"]]
        blocks.append(block)
    return title, ["Account", "Balance"], _fill(_blocks(*blocks), 2), "lr"


def _text_income_statement(r):
    title = "Income statement %s to %s" % (r["start"], r["end"])
    if r.get("currency") is not None:
        title += " (in %s)" % r["currency"]
    blocks = []
    for key, heading in (("income", "Income"), ("expenses", "Expenses")):
        sec = r[key]
        block = [[heading, "", ""]]
        block += [["  " + a["account"], _mt(a["amount"]), a["percent"] + "%"] for a in sec["accounts"]]
        block += [["Total " + key, _mt(m), ""] for m in sec["total"]]
        blocks.append(block)
    blocks.append([["Net income", _mt(m), ""] for m in r["net"]])
    return title, ["Account", "Amount", "Percent"], _fill(_blocks(*blocks), 3), "lrr"


def _text_cashflow(r):
    title = "Cash flow %s to %s" % (r["start"], r["end"])
    opening = [["Opening balance", _mt(m)] for m in r["opening"]]
    money_in = [["Money in", ""]] + [["  " + a["account"], _mt(a["amount"])] for a in r["inflows"]]
    money_in += [["Total money in", _mt(m)] for m in r["total_in"]]
    money_out = [["Money out", ""]] + [["  " + a["account"], _mt(a["amount"])] for a in r["outflows"]]
    money_out += [["Total money out", _mt(m)] for m in r["total_out"]]
    end = [["Net change", _mt(m)] for m in r["net"]] + [["Closing balance", _mt(m)] for m in r["closing"]]
    return title, ["Account", "Amount"], _fill(_blocks(opening, money_in, money_out, end), 2), "lr"


def _text_register(r):
    title = "Register %s" % r["account"]
    if r["rollup"]:
        title += " (with sub-accounts)"
    if r["start"] is not None:
        title += " %s to %s" % (r["start"], r["end"])
    rows = [["", "", "Opening balance", "", "", _mt(m)] for m in r["opening"]]
    for row in r["rows"]:
        rows.append([row["date"], "" if row["id"] is None else str(row["id"]), row["payee"], row["account"],
                     _mt(row["amount"]), _mt(row["balance"])])
    rows += [["", "", "Closing balance", "", "", _mt(m)] for m in r["closing"]]
    return title, ["Date", "Id", "Payee", "Account", "Amount", "Balance"], rows, "llllrr"


def _text_net_worth(r):
    title = "Net worth %s to %s (by %s)" % (r["start"], r["end"], r["step"])
    rows = []
    for pt in r["points"]:
        if not pt["assets"]:
            rows.append([pt["date"], "", "", ""])
            continue
        for a, l, n in zip(pt["assets"], pt["liabilities"], pt["net"]):
            rows.append([pt["date"], _mt(a), _mt(l), _mt(n)])
    return title, ["Date", "Assets", "Liabilities", "Net"], rows, "lrrr"


_TEXT = {
    "trial_balance": _text_trial_balance,
    "balance_sheet": _text_balance_sheet,
    "income_statement": _text_income_statement,
    "cashflow": _text_cashflow,
    "register": _text_register,
    "net_worth": _text_net_worth,
}


def render_text(report):
    kind = _report_kind(report)
    try:
        title, headers, rows, align = _TEXT[kind](report)
    except (KeyError, TypeError, AttributeError, IndexError, ValueError):
        raise ReportError("malformed %s report" % kind) from None
    return title + "\n\n" + render_table(headers, rows, align)


# -- CSV ------------------------------------------------------------------

def _csv_trial_balance(r):
    rows = []
    for a in r["accounts"]:
        side = a["debit"] or a["credit"]
        rows.append([a["account"], a["type"], side["currency"],
                     a["debit"]["amount"] if a["debit"] else "", a["credit"]["amount"] if a["credit"] else ""])
    return ["account", "type", "currency", "debit", "credit"], rows


def _csv_balance_sheet(r):
    rows = []
    for key in ("assets", "liabilities", "equity"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["balance"]["currency"], a["balance"]["amount"]])
    for m in r["equity"]["retained_earnings"]:
        rows.append(["equity", "Retained earnings", m["currency"], m["amount"]])
    return ["section", "account", "currency", "balance"], rows


def _csv_income_statement(r):
    rows = []
    for key in ("income", "expenses"):
        for a in r[key]["accounts"]:
            rows.append([key, a["account"], a["amount"]["currency"], a["amount"]["amount"], a["percent"]])
    return ["section", "account", "currency", "amount", "percent"], rows


def _csv_cashflow(r):
    rows = [["opening", "", m["currency"], m["amount"]] for m in r["opening"]]
    rows += [["in", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["inflows"]]
    rows += [["out", a["account"], a["amount"]["currency"], a["amount"]["amount"]] for a in r["outflows"]]
    rows += [["closing", "", m["currency"], m["amount"]] for m in r["closing"]]
    return ["section", "account", "currency", "amount"], rows


def _csv_register(r):
    rows = [[row["date"], "" if row["id"] is None else str(row["id"]), row["payee"], row["narration"],
             row["account"], row["amount"]["currency"], row["amount"]["amount"], row["balance"]["amount"]]
            for row in r["rows"]]
    return ["date", "id", "payee", "narration", "account", "currency", "amount", "balance"], rows


def _csv_net_worth(r):
    rows = []
    for pt in r["points"]:
        for a, l, n in zip(pt["assets"], pt["liabilities"], pt["net"]):
            rows.append([pt["date"], a["currency"], a["amount"], l["amount"], n["amount"]])
    return ["date", "currency", "assets", "liabilities", "net"], rows


_CSV = {
    "trial_balance": _csv_trial_balance,
    "balance_sheet": _csv_balance_sheet,
    "income_statement": _csv_income_statement,
    "cashflow": _csv_cashflow,
    "register": _csv_register,
    "net_worth": _csv_net_worth,
}


def report_to_csv(report):
    kind = _report_kind(report)
    try:
        headers, rows = _CSV[kind](report)
    except (KeyError, TypeError, AttributeError, IndexError, ValueError):
        raise ReportError("malformed %s report" % kind) from None
    return to_csv(headers, rows)

